def add(title,category,brief,data,expected,notes='',files=None):
    assert len(expected)==5
    i=len(jobs)+1; tag='WK-'+str(r.randrange(100000,999999))
    fields=', '.join(expected)
    evidence=json.dumps(data,ensure_ascii=False,indent=2)
    prompt=f'You are handling workplace ticket {tag}: {title}. {brief}\nUse only the supplied evidence; do not invent missing facts. This is a read-only analysis deliverable: do not change files or execute production actions. Return one JSON object with exactly these fields: {fields}. {notes}\n'
    f=files or {}
    if f: prompt+='The evidence is in the workspace files listed below. Read the relevant contents to answer.\n'+json.dumps(list(f))
    else: prompt+='Evidence:\n'+evidence
    jobs.append(dict(id=f'industry-{i:02}',family=f'workplace-{i:02}',variant=0,split='validation',domain=category,title=title,prompt=prompt,history=[],files=f,toolParity='full'))
    keys.append(dict(id=f'industry-{i:02}',title=title,expected=expected,criteria=[dict(field=k,expected=v,weight=20) for k,v in expected.items()]))
